<script lang="ts">
  import { docsUrl } from "$lib/links";

  const label =
    "Architecture diagram. Write path: your apps and agents send logs and traces to Rootprint, which forwards them to Quickwit, which indexes them into your object storage (S3, GCS or Azure). Quickwit can also pull directly from Kafka, Kinesis or SQS. Read path: search results come from your bucket through Quickwit and Rootprint back to you. Rootprint keeps users, keys and settings in Postgres. Everything except your apps runs in your infrastructure: three containers and one bucket.";
</script>

{#snippet side(
  x: number,
  y: number,
  w: number,
  icon: string,
  role: string,
  name: string,
)}
  <rect class="box" {x} {y} width={w} height="56" />
  <use href="#arch-{icon}" x={x + 12} y={y + 16} width="24" height="24" />
  <text class="role" x={x + 44} y={y + 23}>{role}</text>
  <text class="name" x={x + 44} y={y + 41}>{name}</text>
{/snippet}

{#snippet main(
  x: number,
  y: number,
  w: number,
  h: number,
  icons: string[],
  role: string,
  name: string,
)}
  {@const size = icons.length > 1 ? 22 : 28}
  {@const left = x + (w - icons.length * size - (icons.length - 1) * 10) / 2}
  {@const top = y + (h - 76) / 2}
  <rect class="box" {x} {y} width={w} height={h} />
  {#each icons as icon, i (icon)}
    {#if icon === "rp"}
      <rect class="accent" {x} {y} width={w} height="2" />
      <image
        href="/images/rp-mark-inverted-256.png"
        x={left}
        y={top}
        width={size}
        height={size}
      />
    {:else}
      <use
        href="#arch-{icon}"
        x={left + i * (size + 10)}
        y={top + (28 - size) / 2}
        width={size}
        height={size}
      />
    {/if}
  {/each}
  <text class="role" x={x + w / 2} y={top + 52} text-anchor="middle"
    >{role}</text
  >
  <text class="name" x={x + w / 2} y={top + 71} text-anchor="middle"
    >{name}</text
  >
{/snippet}

{#snippet legend(x: number, y: number)}
  <line class="write" x1={x} y1={y} x2={x + 20} y2={y} />
  <text class="hint" x={x + 28} y={y + 4}>write</text>
  <line class="read" x1={x + 76} y1={y} x2={x + 96} y2={y} />
  <text class="hint" x={x + 104} y={y + 4}>read</text>
{/snippet}

