<style>
  .arch {
    margin-top: 32px;
    border: 1px solid var(--hairline-strong);
    background: var(--base-100);
    padding: 28px 32px;
    color: var(--base-content);
  }
  .arch svg {
    display: block;
    width: 100%;
    height: auto;
    font-family: var(--font-mono);
  }
  .arch .defs {
    position: absolute;
    width: 0;
    height: 0;
  }
  .arch .narrow {
    display: none;
    max-width: 400px;
    margin: 0 auto;
  }
  @media (max-width: 860px) {
    .arch {
      padding: 20px 12px;
    }
    .arch .wide {
      display: none;
    }
    .arch .narrow {
      display: block;
    }
  }

  .box {
    fill: var(--base-200);
    stroke: var(--hairline-strong);
  }
  .accent {
    fill: var(--primary);
  }
  .frame {
    fill: none;
    stroke: var(--hairline-strong);
    stroke-dasharray: 4 4;
  }
  .frame-gap {
    fill: var(--base-100);
  }
  .name {
    font-size: 13px;
    font-weight: 600;
    fill: var(--base-content);
  }
  .role,
  .caption {
    font-size: 10px;
    font-weight: 500;
    letter-spacing: 0.14em;
    fill: var(--base-content-faint);
  }
  .hint {
    font-size: 10.5px;
    letter-spacing: 0.06em;
    fill: var(--base-content-faint);
  }
  .write,
  .read,
  .state {
    fill: none;
  }
  path.write {
    marker-end: url(#arch-arrow-write);
  }
  path.read {
    marker-end: url(#arch-arrow-read);
  }
  .write {
    stroke: var(--primary-strong);
    stroke-width: 1.5;
  }
  .read {
    stroke: var(--base-content);
  }
  .state {
    stroke: var(--base-content);
    stroke-dasharray: 2 3;
  }
  .pull {
    stroke-dasharray: 4 3;
  }
  .head-write {
    fill: var(--primary-strong);
  }
  .head-read {
    fill: var(--base-content);
  }
</style>
